#include <bits/stdc++.h>
using namespace std;
using ll =long long;
ll solution(vector<ll> &x){
    int n=x.size()/3;
    sort(x.rbegin(),x.rend());
    vector<ll> prefix(3*n+1,0);
    for(int i=0;i<3*n;i++){
        prefix[i+1]=prefix[i]+x[i];
    }
    auto value = [&](int a, int b)->ll{
        int k = a+2*b;
        int l = n-a-b;
        int m = k + 3*l;
        return 6* prefix[a] + 4* (prefix[k]-prefix[a])+ 3*(prefix[m]-prefix[k]);
    };
    ll answer = 0;
    for(int i =0;i<=n;i++){
        int low = 0;
        int high =n-i;
        while(low <high){
            int mid = (low + high )/2;
            if(value(i,mid+1)>=value(i,mid)){
                low = mid +1;
            }
            else{
                high =mid;
            }
        }
        answer = max(answer, value(i,low));
        if(low>0){
            answer =max(answer, value(i,low-1));
        
        }
    }
    return answer;
}
int main() {
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>> n;
	    vector<ll> vec(3*n);
	    for(ll & a: vec){
	        cin>>a;
	    }cout<<solution(vec)<<endl;
	}return 0;
	
}
